const getVec = () => {

    const nVecs = NJSCORE.NVectorUtility.GetSpherecVecs3dRandomWithThicknessOffset(500, 15, 0.15);
    const vecs = [];
    for (let i = 0; i < nVecs.length; ++i) {
        vecs.push(new THREE.Vector3(nVecs[i].x, nVecs[i].y, nVecs[i].z));
    }
    return vecs;
}
const initNode = (vecs: THREE.Vector3[]) => {
    let DOT_COLOR = NJSCORE.ColorUtility.GetRandomHex(); //  '#7116b7';
    let positions = []; let colors = []; let sizes = []; let nodes = [];
    for (let i = 0; i < vecs.length; ++i) {
        positions.push(vecs[i].x, vecs[i].y, vecs[i].z);
        let col = NJSCORE.ColorUtility.GetRandomColorByLightness(DOT_COLOR, 0.2 + Math.random() * 0.7);
        colors.push(col[0] / 255, col[1] / 255, col[2] / 255, Math.random());
        // console.log(col[0] / 255, col[1] / 255, col[2] / 255, Math.random())
        let size = i * 0.0001; // PARTICLE_SIZE + (Math.random() - 0.5) * 0.15;
        // let size = i + PARTICLE_SIZE + (Math.random() - 0.5) * 0.15;
        sizes.push(size);
        const dot = new Node(i, vecs[i], col, size);
        nodes.push(dot);
    }
    return [positions, colors, sizes];
}
const shaderVert = `
    attribute float size;
    attribute vec4 customColor;
    varying vec4 vColor;

    void main() {
        // vColor = vec4(vColor.xyz, distance(vec3(customColor.xyz), position));
        vColor = customColor;
        vec4 mvPosition = modelViewMatrix * vec4( position, 1.0 );
        gl_PointSize = size * ( 30.0 / -mvPosition.z );
        gl_Position = projectionMatrix * mvPosition;
    }
    `;

const shaderFrag = `
    uniform vec3 color;
    uniform sampler2D texture;
    varying vec4 vColor;

	void main() {
        gl_FragColor = vColor; // vec4(color * vColor, 1.0);
        // gl_FragColor = gl_FragColor * texture2D(texture, gl_PointCoord);
        // if (gl_FragColor.a < 0.5) discard;
    }
    `;

